<script setup lang="ts">
import{ref,onMounted}from'vue';const props=defineProps<{admin:boolean}>(),emit=defineEmits<{navigate:[view:string]}>(),data=ref<any>({stats:{},recentDiagnoses:[],recentDocuments:[]}),error=ref('');
onMounted(async()=>{try{const r=await fetch('/api/dashboard',{headers:{Authorization:'Bearer '+sessionStorage.getItem('ops-token')}}),b=await r.json();if(!r.ok)throw Error(b.message);data.value=b.data}catch(e){error.value=e instanceof Error?e.message:'加载失败'}});
</script>
<template><section class="dashboard"><div class="dashboard-hero"><div><span class="eyebrow">OPERATIONS KNOWLEDGE HUB</span><h1>今天，从可靠知识开始判断。</h1><p>查询企业资料、辅助定位故障，并持续发现团队知识缺口。</p></div><button @click="emit('navigate','assistant')">向知识助手提问 →</button></div><p v-if="error" class="banner error">{{error}}</p><div class="dashboard-stats"><article><span>▤</span><small>有效知识库</small><strong>{{data.stats.knowledgeBases||0}}</strong></article><article><span>✓</span><small>已发布资料</small><strong>{{data.stats.publishedDocuments||0}}</strong></article><article><span>✦</span><small>问答会话</small><strong>{{data.stats.conversations||0}}</strong></article><article><span>⌁</span><small>诊断记录</small><strong>{{data.stats.diagnoses||0}}</strong></article><article v-if="admin"><span>!</span><small>待处理缺口</small><strong>{{data.stats.openGaps||0}}</strong></article></div><div class="dashboard-main"><section class="dashboard-panel"><div class="panel-title"><h2>快捷工作区</h2><small>常用能力</small></div><div class="quick-grid"><button @click="emit('navigate','assistant')"><b>✦ 知识问答</b><span>基于已发布资料获取有引用的回答</span></button><button @click="emit('navigate','diagnosis')"><b>⌁ 故障诊断</b><span>组合发布、故障记录和 SOP 梳理路径</span></button><button @click="emit('navigate','knowledge')"><b>▤ 知识文档</b><span>{{admin?'上传、发布并维护版本':'阅读当前有效资料'}}</span></button><button v-if="admin" @click="emit('navigate','gaps')"><b>! 缺口雷达</b><span>查看团队反复提出但缺少依据的问题</span></button></div></section><section class="dashboard-panel"><div class="panel-title"><h2>最近诊断</h2><button class="text-btn" @click="emit('navigate','diagnosis')">查看全部</button></div><article v-for="d in data.recentDiagnoses" class="activity-row"><span class="activity-dot"></span><div><b>{{d.SERVICE_NAME}}</b><p>{{d.SYMPTOM}}</p></div><small>{{d.STATUS==='RESOLVED'?'已解决':'待确认'}}</small></article><div v-if="!data.recentDiagnoses.length" class="empty">暂无诊断记录</div></section></div><section class="dashboard-panel recent-docs"><div class="panel-title"><h2>最近发布的知识</h2><button class="text-btn" @click="emit('navigate','knowledge')">进入文档中心</button></div><article v-for="d in data.recentDocuments"><span class="doc-icon">▤</span><div><b>{{d.TITLE}}</b><small>{{d.VERSION_NO}}</small></div><small>{{d.PUBLISHED_AT?new Date(d.PUBLISHED_AT).toLocaleDateString():'-'}}</small></article></section></section></template>
